head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > getAllPopupList]<br/>현재 열려 있는 모든 팝업 객체를 Scope 및 팝업 유형에 관계없이 배열로 반환합니다.",
    "validation" : [
        "열려 있는 모든 팝업 객체들의 배열을 반환해야 합니다.",
        "열려 있는 팝업이 없으면 빈 배열([])을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openPopup_onclick = function () {
    var popupId = par_popupId.getValue();

    var options = {
        id: popupId,
        type: "wframePopup",
        width: "400px",
        height: "250px",
        top: "100px",
        left: "100px",
        popupName: popupId,
        modal: false
    };

    $p.openPopup("/sample/common_link/util_createPopup_1.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (id: " + popupId + ")");
}



scwin.btn_getAllPopupList_onclick = function () {
    var popList = $p.getAllPopupList();

    wf_body_bottom.getObj("scwin").setReturnValue("getAllPopupList() 배열 길이 : " + popList.length);

    if (popList.length > 0) {
        for (var i = 0; i < popList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("  [" + i + "] id : " + popList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열려 있는 팝업 없음 (빈 배열)");
    }
}



scwin.btn_closeAll_onclick = function () {
    var popList = $p.getAllPopupList();
    for (var i = popList.length - 1; i >= 0; i--) {
        $p.closePopup(popList[i].id);
    }

    setTimeout(function () {
        var afterList = $p.getAllPopupList();
        wf_body_bottom.getObj("scwin").setReturnValue("전체 닫기 완료, 남은 팝업 : " + afterList.length + "개");
    }, 500);
}
